from __future__ import annotations
from dataclasses import dataclass
from typing import Callable, Dict

OPERASI: Dict[str, Callable[[float, float], float]] = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": lambda a, b: a / b,
}


@dataclass(frozen=True)
class HasilKalkulasi:
    a: float
    b: float
    op: str
    hasil: float


def kalkulator(a: float, b: float, op: str) -> HasilKalkulasi:
    """Hitung a op b dan kembalikan objek HasilKalkulasi.

    Raises:
        ValueError: operator tidak dikenali.
        ZeroDivisionError: pembagian dengan nol.
    """
    if op not in OPERASI:
        raise ValueError(f"Operator '{op}' tidak dikenali")
    if op == "/" and b == 0:
        raise ZeroDivisionError("Pembagi tidak boleh nol")
    return HasilKalkulasi(a, b, op, OPERASI[op](a, b))


