def binary_search(harga: list, target: int) -> int:
    """Mencari indeks target pada list harga yang sudah terurut ascending.
    Mengembalikan indeks jika ditemukan, atau -1 jika tidak."""
    kiri, kanan = 0, len(harga) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        if harga[tengah] == target:
            return tengah
        elif harga[tengah] < target:
            kiri = tengah + 1
        else:
            kanan = tengah - 1
    return -1

